CREATE TABLE public.staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role text NOT NULL CHECK(role IN ('customer','business_owner','listing_moderator','support','sales','content_manager','finance','super_admin')),city text,category text,created_at timestamptz NOT NULL DEFAULT now(),granted_by uuid);
GRANT SELECT ON public.staff_assignments TO authenticated; GRANT ALL ON public.staff_assignments TO service_role;
ALTER TABLE public.staff_assignments ENABLE ROW LEVEL SECURITY;
INSERT INTO public.staff_assignments(user_id,role) SELECT user_id,'super_admin' FROM public.user_roles WHERE role='admin';
CREATE OR REPLACE FUNCTION public.has_permission(permission text,bid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.staff_assignments s WHERE s.user_id=auth.uid() AND (s.role='super_admin' OR (CASE s.role WHEN 'listing_moderator' THEN permission IN ('claims.review','verification.review','reviews.moderate','listings.moderate','audit.read') WHEN 'support' THEN permission IN ('claims.read','reviews.read') WHEN 'sales' THEN permission IN ('listings.read') WHEN 'content_manager' THEN permission IN ('listings.read','catalogue.read') WHEN 'finance' THEN permission IN ('entitlements.read','audit.read') ELSE false END) AND (s.city IS NULL AND s.category IS NULL OR bid IS NOT NULL AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=bid AND (s.city IS NULL OR s.city=b.city) AND (s.category IS NULL OR s.category=b.category))))); $$;
REVOKE ALL ON FUNCTION public.has_permission(text,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_permission(text,uuid) TO authenticated;
CREATE POLICY "own or super staff assignments" ON public.staff_assignments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_permission('staff.manage'));
CREATE OR REPLACE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.staff_assignments WHERE user_id=auth.uid() AND role NOT IN ('customer','business_owner')); $$;
GRANT EXECUTE ON FUNCTION public.is_staff() TO authenticated; REVOKE EXECUTE ON FUNCTION public.is_staff() FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',''),NEW.email); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'business_owner'); RETURN NEW; END; $$;
REVOKE INSERT,UPDATE,DELETE ON public.user_roles FROM authenticated;
CREATE OR REPLACE FUNCTION public.protect_admin_removal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(4298841); IF TG_TABLE_NAME='user_roles' THEN IF OLD.role='admin' AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE role='admin' AND user_id<>OLD.user_id) THEN RAISE EXCEPTION 'Cannot remove the last authorized administrator'; END IF; ELSE IF OLD.role='super_admin' AND NOT EXISTS(SELECT 1 FROM public.staff_assignments WHERE role='super_admin' AND id<>OLD.id) THEN RAISE EXCEPTION 'Cannot remove the last super admin'; END IF; END IF; RETURN OLD; END; $$;
CREATE TRIGGER protect_legacy_admin BEFORE DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.protect_admin_removal();
CREATE TRIGGER protect_super_admin BEFORE DELETE ON public.staff_assignments FOR EACH ROW EXECUTE FUNCTION public.protect_admin_removal();
CREATE OR REPLACE FUNCTION public.set_staff_assignment(target_user uuid,staff_role text,scope_city text,scope_category text,remove_role boolean,decision_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(4298841); IF NOT public.has_permission('staff.manage') OR target_user=auth.uid() OR length(trim(decision_reason))<5 THEN RAISE EXCEPTION 'Role change denied; another super admin and a reason are required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target_user) THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF staff_role='super_admin' AND (scope_city IS NOT NULL OR scope_category IS NOT NULL) THEN RAISE EXCEPTION 'Super admin cannot be scoped'; END IF;
IF remove_role THEN DELETE FROM public.staff_assignments WHERE user_id=target_user AND role=staff_role AND city IS NOT DISTINCT FROM scope_city AND category IS NOT DISTINCT FROM scope_category; IF staff_role='super_admin' THEN DELETE FROM public.user_roles WHERE user_id=target_user AND role='admin'; END IF; ELSE INSERT INTO public.staff_assignments(user_id,role,city,category,granted_by) VALUES(target_user,staff_role,scope_city,scope_category,auth.uid()); IF staff_role='super_admin' THEN INSERT INTO public.user_roles(user_id,role) VALUES(target_user,'admin') ON CONFLICT DO NOTHING; END IF; END IF;
INSERT INTO public.directory_audit(entity_id,actor_id,action,note,after_data) VALUES(target_user,auth.uid(),CASE WHEN remove_role THEN 'staff_role_removed' ELSE 'staff_role_granted' END,decision_reason,jsonb_build_object('role',staff_role,'city',scope_city,'category',scope_category)); END; $$;
GRANT EXECUTE ON FUNCTION public.set_staff_assignment(uuid,text,text,text,boolean,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.set_staff_assignment(uuid,text,text,text,boolean,text) FROM PUBLIC,anon;
CREATE TABLE public.business_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),claimant_id uuid NOT NULL,identity_name text NOT NULL,contact text NOT NULL,corrections text NOT NULL DEFAULT '',evidence text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','evidence_requested','under_review','approved','rejected','revoked','expired')),verified_contacts text[] NOT NULL DEFAULT '{}',reviewer_id uuid,reason text NOT NULL DEFAULT '',previous_owner_id uuid,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,expires_at timestamptz);
GRANT SELECT,INSERT ON public.business_claims TO authenticated; GRANT ALL ON public.business_claims TO service_role;
ALTER TABLE public.business_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY "claim parties read" ON public.business_claims FOR SELECT TO authenticated USING(claimant_id=auth.uid() OR public.has_permission('claims.read',business_id) OR public.has_permission('claims.review',business_id));
CREATE POLICY "submit own existing listing claim" ON public.business_claims FOR INSERT TO authenticated WITH CHECK(claimant_id=auth.uid() AND status='submitted' AND reviewer_id IS NULL AND decided_at IS NULL AND previous_owner_id IS NULL AND verified_contacts='{}' AND reason='' AND expires_at IS NULL AND EXISTS(SELECT 1 FROM public.businesses WHERE id=business_id AND status='approved' AND archived_at IS NULL));
CREATE OR REPLACE FUNCTION public.validate_claim() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(trim(NEW.identity_name))<2 OR length(trim(NEW.contact))<5 OR length(NEW.corrections)>4000 OR cardinality(NEW.evidence)>8 OR EXISTS(SELECT 1 FROM unnest(NEW.evidence) p WHERE p !~ ('^'||NEW.claimant_id::text||'/[a-zA-Z0-9_.-]+$')) THEN RAISE EXCEPTION 'Invalid claim identity or evidence'; END IF; IF TG_OP='INSERT' THEN PERFORM pg_advisory_xact_lock(hashtext(NEW.claimant_id::text)); IF (SELECT count(*) FROM public.business_claims WHERE claimant_id=NEW.claimant_id AND created_at>now()-interval '1 day')>=5 OR EXISTS(SELECT 1 FROM public.business_claims WHERE claimant_id=NEW.claimant_id AND business_id=NEW.business_id AND status IN ('submitted','evidence_requested','under_review','approved')) THEN RAISE EXCEPTION 'Active claim exists or daily limit reached'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_claim_record BEFORE INSERT OR UPDATE ON public.business_claims FOR EACH ROW EXECUTE FUNCTION public.validate_claim();
CREATE POLICY "upload own trust evidence" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='trust-evidence' AND (storage.foldername(name))[1]=auth.uid()::text AND name ~ '^[a-f0-9-]{36}/[a-zA-Z0-9_.-]+$');
CREATE POLICY "private trust evidence read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='trust-evidence' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.business_claims c WHERE name=ANY(c.evidence) AND public.has_permission('claims.review',c.business_id))));
CREATE TABLE public.business_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES public.businesses(id),scope text NOT NULL,public_summary text NOT NULL,evidence_reference text NOT NULL,reviewer_id uuid NOT NULL,checked_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')),reason text NOT NULL);
GRANT SELECT ON public.business_verifications TO authenticated; GRANT ALL ON public.business_verifications TO service_role;
ALTER TABLE public.business_verifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "staff verification read" ON public.business_verifications FOR SELECT TO authenticated USING(public.has_permission('verification.review',business_id));
CREATE TABLE public.review_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),review_id uuid NOT NULL REFERENCES public.reviews(id),reporter_id uuid NOT NULL,reason text NOT NULL CHECK(reason IN ('spam','duplicate','harassment','personal_data','conflict_of_interest','other')),evidence text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','upheld','dismissed','appealed','resolved')),decision_reason text NOT NULL DEFAULT '',reviewer_id uuid,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,appeal text NOT NULL DEFAULT '',UNIQUE(review_id,reporter_id));
GRANT SELECT,INSERT ON public.review_reports TO authenticated; GRANT ALL ON public.review_reports TO service_role;
ALTER TABLE public.review_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own or moderator report read" ON public.review_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=review_id AND public.has_permission('reviews.moderate',r.business_id)));
CREATE POLICY "customer reports published review" ON public.review_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='submitted' AND reviewer_id IS NULL AND decided_at IS NULL AND decision_reason='' AND appeal='' AND length(evidence)<=4000 AND EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=review_id AND r.status='published'));
CREATE POLICY "scoped staff listing reads" ON public.businesses FOR SELECT TO authenticated USING(public.has_permission('listings.moderate',id) OR public.has_permission('listings.read',id) OR public.has_permission('claims.review',id));
CREATE POLICY "scoped moderator review reads" ON public.reviews FOR SELECT TO authenticated USING(public.has_permission('reviews.moderate',business_id));
CREATE POLICY "scoped staff audit reads" ON public.directory_audit FOR SELECT TO authenticated USING(public.has_permission('audit.read',business_id));
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='guard_business'; def:=replace(def,'IF NOT public.has_role(auth.uid(),''admin'') THEN','IF NOT (public.has_role(auth.uid(),''admin'') OR (current_user IN (''postgres'',''supabase_admin'') AND current_setting(''app.trust_authorized'',true)=''true'')) THEN'); EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.decide_claim(claim_id uuid,next_state text,decision_reason text,contact_checks text[],expiry timestamptz DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.business_claims; b public.businesses; BEGIN SELECT * INTO c FROM public.business_claims WHERE id=claim_id FOR UPDATE; IF NOT FOUND OR NOT public.has_permission('claims.review',c.business_id) OR c.claimant_id=auth.uid() OR length(trim(decision_reason))<5 THEN RAISE EXCEPTION 'Claim decision denied'; END IF; SELECT * INTO b FROM public.businesses WHERE id=c.business_id FOR UPDATE; IF NOT ((c.status='submitted' AND next_state IN ('evidence_requested','under_review','rejected')) OR (c.status='evidence_requested' AND next_state IN ('under_review','rejected')) OR (c.status='under_review' AND next_state IN ('approved','rejected','evidence_requested')) OR (c.status='approved' AND next_state IN ('revoked','expired'))) THEN RAISE EXCEPTION 'Invalid claim transition'; END IF; IF next_state='approved' THEN IF cardinality(c.evidence)=0 OR cardinality(contact_checks)=0 OR expiry IS NOT NULL AND expiry<=now() OR EXISTS(SELECT 1 FROM public.business_claims WHERE business_id=c.business_id AND id<>c.id AND status='approved') THEN RAISE EXCEPTION 'Approval needs evidence, independently checked contact and resolved competing claims'; END IF; PERFORM set_config('app.trust_authorized','true',true); UPDATE public.businesses SET owner_id=c.claimant_id WHERE id=c.business_id; UPDATE public.business_claims SET previous_owner_id=b.owner_id WHERE id=c.id; ELSIF next_state IN ('revoked','expired') THEN IF next_state='expired' AND (c.expires_at IS NULL OR c.expires_at>now()) THEN RAISE EXCEPTION 'Claim has not expired'; END IF; IF b.owner_id=c.claimant_id AND c.previous_owner_id IS NOT NULL THEN PERFORM set_config('app.trust_authorized','true',true); UPDATE public.businesses SET owner_id=c.previous_owner_id WHERE id=c.business_id; END IF; END IF;
UPDATE public.business_claims SET status=next_state,reviewer_id=auth.uid(),reason=decision_reason,verified_contacts=coalesce(contact_checks,'{}'),decided_at=now(),expires_at=expiry WHERE id=c.id; INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,note,before_data,after_data) VALUES(c.business_id,c.id,auth.uid(),'claim_'||next_state,decision_reason,jsonb_build_object('state',c.status,'owner',b.owner_id),jsonb_build_object('state',next_state)); END; $$;
CREATE OR REPLACE FUNCTION public.add_claim_evidence(claim_id uuid,paths text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.business_claims; BEGIN SELECT * INTO c FROM public.business_claims WHERE id=claim_id FOR UPDATE; IF NOT FOUND OR c.claimant_id<>auth.uid() OR c.status NOT IN ('submitted','evidence_requested') THEN RAISE EXCEPTION 'Evidence update denied'; END IF; UPDATE public.business_claims SET evidence=paths WHERE id=claim_id; END; $$;
CREATE OR REPLACE FUNCTION public.record_business_verification(bid uuid,checked_scope text,summary text,evidence_ref text,decision_reason text,expiry timestamptz DEFAULT NULL,revoke_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE vid uuid; BEGIN IF NOT public.has_permission('verification.review',bid) OR length(trim(decision_reason))<5 THEN RAISE EXCEPTION 'Verification denied'; END IF; IF revoke_id IS NOT NULL THEN UPDATE public.business_verifications SET status='revoked',reason=decision_reason WHERE id=revoke_id AND business_id=bid RETURNING id INTO vid; IF vid IS NULL THEN RAISE EXCEPTION 'Verification unavailable'; END IF; ELSE IF length(trim(checked_scope))<3 OR length(trim(summary))<3 OR length(trim(evidence_ref))<5 OR expiry IS NOT NULL AND expiry<=now() THEN RAISE EXCEPTION 'Scope, evidence and valid expiry required'; END IF; INSERT INTO public.business_verifications(business_id,scope,public_summary,evidence_reference,reviewer_id,expires_at,reason) VALUES(bid,checked_scope,summary,evidence_ref,auth.uid(),expiry,decision_reason) RETURNING id INTO vid; END IF; INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,note,after_data) VALUES(bid,vid,auth.uid(),'verification_decision',decision_reason,jsonb_build_object('scope',checked_scope,'revoked',revoke_id IS NOT NULL)); END; $$;
CREATE OR REPLACE FUNCTION public.public_verification(bid uuid) RETURNS TABLE(scope text,summary text,checked_at timestamptz,expires_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.scope,v.public_summary,v.checked_at,v.expires_at FROM public.business_verifications v JOIN public.businesses b ON b.id=v.business_id WHERE v.business_id=bid AND b.status='approved' AND b.archived_at IS NULL AND v.status='active' AND (v.expires_at IS NULL OR v.expires_at>now()); $$;
GRANT EXECUTE ON FUNCTION public.public_verification(uuid) TO anon,authenticated; REVOKE EXECUTE ON FUNCTION public.public_verification(uuid) FROM PUBLIC;
ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS moderation_reason text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.decide_review_report(report_id uuid,uphold boolean,decision_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.review_reports; r public.reviews; BEGIN SELECT * INTO p FROM public.review_reports WHERE id=report_id FOR UPDATE; SELECT * INTO r FROM public.reviews WHERE id=p.review_id; IF p.id IS NULL OR NOT public.has_permission('reviews.moderate',r.business_id) OR p.status NOT IN ('submitted','appealed') OR length(trim(decision_reason))<5 THEN RAISE EXCEPTION 'Review decision denied'; END IF; PERFORM set_config('app.trust_review','true',true); IF uphold THEN UPDATE public.reviews SET status='hidden',moderation_reason=decision_reason WHERE id=r.id; ELSIF p.status='appealed' THEN UPDATE public.reviews SET status='published',moderation_reason=decision_reason WHERE id=r.id; END IF; UPDATE public.review_reports SET status=CASE WHEN uphold THEN 'upheld' ELSE 'dismissed' END,decision_reason=decide_review_report.decision_reason,reviewer_id=auth.uid(),decided_at=now() WHERE id=p.id; INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,note,before_data,after_data) VALUES(r.business_id,r.id,auth.uid(),'review_report_decision',decision_reason,jsonb_build_object('status',r.status),jsonb_build_object('upheld',uphold)); END; $$;
CREATE OR REPLACE FUNCTION public.appeal_review_report(report_id uuid,appeal_text text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(trim(appeal_text))<10 OR length(appeal_text)>4000 THEN RAISE EXCEPTION 'Explain the appeal'; END IF; UPDATE public.review_reports p SET appeal=appeal_text,status='appealed' WHERE p.id=report_id AND p.status IN ('upheld','dismissed') AND (p.reporter_id=auth.uid() OR EXISTS(SELECT 1 FROM public.reviews r WHERE r.id=p.review_id AND r.user_id=auth.uid())); IF NOT FOUND THEN RAISE EXCEPTION 'Appeal denied'; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.guard_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.has_role(auth.uid(),'admin') OR (current_user IN ('postgres','supabase_admin') AND current_setting('app.trust_review',true)='true') THEN IF NEW.status IS DISTINCT FROM OLD.status AND length(trim(NEW.moderation_reason))<5 THEN RAISE EXCEPTION 'Moderation reason required'; END IF; RETURN NEW; END IF; NEW.status:=OLD.status; NEW.rating:=OLD.rating; NEW.text:=OLD.text; NEW.name:=OLD.name; NEW.business_id:=OLD.business_id; NEW.user_id:=OLD.user_id; NEW.moderation_reason:=OLD.moderation_reason; IF length(coalesce(NEW.owner_reply,''))>1000 THEN RAISE EXCEPTION 'Reply too long'; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.audit_trust_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_json jsonb; after_json jsonb; bid uuid; BEGIN IF TG_TABLE_NAME='businesses' THEN bid:=NEW.id; before_json:=jsonb_build_object('status',OLD.status,'owner_id',OLD.owner_id,'verified',OLD.verified,'plan',OLD.plan,'sponsored',OLD.sponsored,'archived',OLD.archived_at IS NOT NULL); after_json:=jsonb_build_object('status',NEW.status,'owner_id',NEW.owner_id,'verified',NEW.verified,'plan',NEW.plan,'sponsored',NEW.sponsored,'archived',NEW.archived_at IS NOT NULL); ELSE bid:=NEW.business_id; before_json:=jsonb_build_object('status',OLD.status,'owner_reply_changed',false); after_json:=jsonb_build_object('status',NEW.status,'owner_reply_changed',NEW.owner_reply IS DISTINCT FROM OLD.owner_reply); END IF; IF before_json IS DISTINCT FROM after_json THEN INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,before_data,after_data,note) VALUES(bid,NEW.id,auth.uid(),TG_TABLE_NAME||'_sensitive_change',before_json,after_json,coalesce(nullif(current_setting('app.trust_reason',true),''),'Recorded by database safeguard')); END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_listing_trust AFTER UPDATE ON public.businesses FOR EACH ROW EXECUTE FUNCTION public.audit_trust_change();
CREATE TRIGGER audit_review_trust AFTER UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.audit_trust_change();
CREATE OR REPLACE FUNCTION public.validate_review_submission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.user_id IS NOT NULL AND NEW.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Review identity mismatch'; END IF; IF NEW.rating NOT BETWEEN 1 AND 5 OR length(trim(NEW.text))<10 OR length(NEW.text)>4000 OR length(trim(NEW.name))<2 THEN RAISE EXCEPTION 'Invalid review'; END IF; PERFORM pg_advisory_xact_lock(hashtext(NEW.business_id::text)); IF EXISTS(SELECT 1 FROM public.reviews WHERE business_id=NEW.business_id AND lower(trim(text))=lower(trim(NEW.text))) THEN RAISE EXCEPTION 'Duplicate review'; END IF; IF NEW.user_id IS NOT NULL AND (SELECT count(*) FROM public.reviews WHERE user_id=NEW.user_id AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Review rate limit reached'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_review_insert BEFORE INSERT ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.validate_review_submission();
GRANT EXECUTE ON FUNCTION public.decide_claim(uuid,text,text,text[],timestamptz),public.add_claim_evidence(uuid,text[]),public.record_business_verification(uuid,text,text,text,text,timestamptz,uuid),public.decide_review_report(uuid,boolean,text),public.appeal_review_report(uuid,text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.decide_claim(uuid,text,text,text[],timestamptz),public.add_claim_evidence(uuid,text[]),public.record_business_verification(uuid,text,text,text,text,timestamptz,uuid),public.decide_review_report(uuid,boolean,text),public.appeal_review_report(uuid,text) FROM PUBLIC,anon;